{"foils":[{"nl":"Copy the first half of the rows onto the second half in reverse row order, preserving dimensions.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h//2): out[h-1-r]=grid[r][:]
    return out"},{"nl":"Copy the topmost row into every row of the bottom half.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h//2,h): out[r]=grid[0][:]
    return out"},{"nl":"Copy the upper half downward, but only replace zero cells in the lower half.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h//2,h):
        src=r-h//2
        for c in range(len(grid[0])):
            if out[r][c]==0: out[r][c]=grid[src][c]
    return out"},{"nl":"Repeat the first row-pattern throughout the grid at the same vertical spacing.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h): out[r]=grid[r%(max(1,h//2))][:]
    return out"},{"nl":"Copy the upper half onto the lower half without reversing, and clear any unmatched final row.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h//2):
        if r+h//2<h: out[r+h//2]=grid[r][:]
    return out"},{"nl":"Copy the top half onto the bottom half, changing all copied nonzero cells to the color of the first copied cell.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]; vals=[x for row in grid[:h//2] for x in row if x]
    col=vals[0] if vals else 0
    for r in range(h//2,h): out[r]=[col if x else 0 for x in grid[r-h//2]]
    return out"},{"nl":"Copy each row from the upper half to the corresponding lower row only when that source row contains a nonzero cell.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h//2):
        if any(grid[r]): out[r+h//2]=grid[r][:]
    return out"},{"nl":"Mirror the upper half vertically into the lower half, but preserve the original lower-half background zeros.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h//2):
        for c,x in enumerate(grid[r]):
            if x: out[h-1-r][c]=x
    return out"},{"nl":"Tile the first two rows repeatedly down the grid.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h): out[r]=grid[r%2][:]
    return out"},{"nl":"Copy the upper half onto the lower half, but only copy cells whose source value is 8 or 9.","code":"def transform(grid):
    h=len(grid); out=[row[:] for row in grid]
    for r in range(h//2):
        for c,x in enumerate(grid[r]):
            if x in (8,9): out[r+h//2][c]=x
    return out"}]}

